/**
 * /pages/MedicineCatalogGroup.jsx
 * ---------------------------------------------------------------------------
 * Route con CẤP 3 của `/medicine` — path 'group/:id' của `/medicine/catalog`.
 * Nhận `id` từ url qua `props: true`.
 */

import React from 'react'
import { Card, Descriptions, Button, Tag } from 'antd'
import { ArrowLeftOutlined } from '@ant-design/icons'

import { useRouter, useRoute } from '@/router'
import { useI18n } from '@/lang'

const MedicineCatalogGroup = ({ id }) => {
  const router = useRouter()
  const route = useRoute()
  const { t } = useI18n()

  return (
    <Card
      size="small"
      title={t('Nhóm thuốc')}
      extra={
        <Button
          icon={<ArrowLeftOutlined />}
          onClick={() => router.push({ name: 'medicine-catalog-list' })}
        >
          {t('Quay lại')}
        </Button>
      }
    >
      <Descriptions column={{ xs: 1, sm: 2 }} bordered size="small">
        <Descriptions.Item label={t('Mã nhóm')}>{`GRP00${id}`}</Descriptions.Item>
        <Descriptions.Item label={t('Tên nhóm')}>
          {`${t('Nhóm thuốc')} #${id}`}
        </Descriptions.Item>
        <Descriptions.Item label={t('Số thuốc')}>
          <Tag color="blue">{Number(id) * 4}</Tag>
        </Descriptions.Item>
        <Descriptions.Item label={t('Route')}>
          {`${route.path} — name: ${route.name}`}
        </Descriptions.Item>
      </Descriptions>
    </Card>
  )
}

export default MedicineCatalogGroup
